function animateWeapon(age){if(shield){shield.visible=hasShield();const bash=Math.max(0,1-(ctx.time()-shieldBash)/.4);shield.position.set(blocking.held?-.31:-.40,blocking.held?-.22:-.42,-.78-bash*.22);shield.rotation.set(0,blocking.held?-.10:-.25,blocking.held?.08:.28)}if(!weapon)return;if(holdingTorch()){weapon.position.set(.33,-.48,-.64);weapon.rotation.set(-.1,0,-.15);weapon.userData.animate(ctx.time());return}const moving=['KeyW','KeyA','KeyS','KeyD'].some(k=>keys.has(k)),bob=moving?Math.sin(ctx.time()*9)*.012:0;weapon.position.set(p.classId==='bow'?.20:.32,-.29+bob,-.55);weapon.rotation.set(0,0,0);const t=Math.max(0,age);if(p.classId==='sword'){weapon.position.set(.33,-.37+bob,-.72);weapon.rotation.set(1.40,.03,-.12);if(t<.5){const phase=t/.5,wind=Math.sin(Math.min(1,phase/.25)*Math.PI/2),cut=phase<.25?0:Math.sin((phase-.25)/.75*Math.PI);weapon.rotation.x+=wind*.2-cut*1.65;weapon.rotation.z-=cut*.65;weapon.position.x-=cut*.25;weapon.position.z-=cut*.10}if(talents.spin){weapon.rotation.set(.1,ctx.time()*10,-.5);weapon.position.set(.05,-.2,-.85)}}else if(p.classId==='bow'){const draw=t<.2?t/.2:t<.28?1-(t-.2)/.08:0;const a=weapon.userData.string.geometry.attributes.position;a.setXYZ(1,0,0,.02+draw*.20);a.needsUpdate=true;weapon.userData.arrow.position.z=draw*.20;weapon.userData.arrow.visible=t<.22||t>.52;weapon.position.z+=t>.22&&t<.45?Math.sin((t-.22)/.23*Math.PI)*.06:0;}else{weapon.rotation.x=-.28;const pulse=t<.6?Math.sin(t/.6*Math.PI):0;weapon.rotation.x-=pulse*.5;weapon.position.z-=pulse*.12;weapon.userData.gem.scale.setScalar(1+pulse*.65)}}
function damage(n,value,damageType=p.classId==='mage'?'magic':'physical'){if(n.hp<=0)return;if(damageType==='physical'&&n.markLeft>0)value*=1.4;value*=ritual.damageMultiplier;value=ctx.admin?.inside?ctx.admin.receive(n,value,damageType):ctx.dungeon?.receive(n,value,damageType)??value;value=ctx.ritual?.receive(n,value,damageType)??value;selectedEnemy=n;n.hp=Math.max(0,n.hp-value);n.hit=true;if(ctx.admin?.inside){ctx.admin.hit(n);return}if(n.species==='troll'&&!n.aggro)ctx.sfx?.('troll-aggro');if(['hunter','witch','troll','lich'].includes(n.species)||n.species?.startsWith('skeleton'))n.aggro=camera.position.clone();if(n.species==='wolf'){n.aggro=camera.position.clone()}if(n===wolf){wolf.mode='attack';wolf.aggroOrigin=camera.position.clone()}if(n.hp===0){if(ctx.chapel?.inside){n.g.visible=false;ctx.chapel.killed(n);kill(p,n.id+'-'+(n.generation||0),'monster',n.species);ctx.sfx?.('skeleton-death');sync();return}if(n.species==='dark-self')return;if(ctx.dungeon?.inside){n.g.visible=false;ctx.dungeon.killed(n,p);kill(p,n.id+'-'+(n.generation||0),'monster');if(n.species.startsWith('skeleton'))ctx.sfx?.('skeleton-death');sync();return}if(n===ctx.world?.hunter){n.g.visible=true;p.stage='hunter_talk';sync();tone(300);return}if(n.species==='witch'&&p.stage==='witch')p.stage='witch_return';n.g.visible=false;kill(p,n===wolf?'wolf':n.id+(n.generation??''),n===wolf||(['wolf','witch','troll'].includes(n.species)||n.species?.startsWith('skeleton'))?'monster':'mob',n===wolf?'wolf':n.species);if(n.species?.startsWith('skeleton')){ctx.sfx?.('skeleton-death');ctx.cemetery?.killed(n);}else ctx.world?.killed(n,p);sync();tone(300)}}
function attack(){if(talents.blocksActions||ctx.ritual?.stunned||!ctx.active()||open||rollAge<ROLL.duration||blocking.held||!p.classId||!weaponEquipped())return;const now=ctx.time(),c=CLASSES[p.classId];if(now-lastAttack<c.cooldown/(gear.attackSpeed||1)*(ctx.ritual?.attackFactor||1))return;const moving=['KeyW','KeyA','KeyS','KeyD'].some(k=>keys.has(k));const manaCost=10*(gear.manaCost||1);if(p.classId==='mage'&&(moving||vitals.mana<manaCost))return;if(p.classId==='bow'&&countItem(slots,'arrow')===0)return;const staminaCost=p.classId==='sword'?12:p.classId==='bow'?8:0;if(vitals.stamina<staminaCost)return;talents.reveal();vitals.stamina-=staminaCost;lastAttack=attackTime=now;const dir=new T.Vector3();camera.getWorldDirection(dir);if(p.classId==='sword'){ctx.sfx?.('sword');let best;for(const n of targets()){const delta=n.g.position.clone().add(new T.Vector3(0,.7,0)).sub(camera.position);if(n.hp>0&&delta.length()<2.6&&delta.normalize().dot(dir)>.65&&(!best||camera.position.distanceTo(n.g.position)<camera.position.distanceTo(best.g.position)))best=n}if(best&&[.2,.4,.6,.8].every(t=>!ctx.blocked(camera.position.clone().lerp(best.g.position,t))))damage(best,criticalDamage(weaponDamage(),ctx.random?.()??Math.random()))}else{if(p.classId==='bow'){spendArrow()}else vitals.mana-=manaCost;const m=new T.Mesh(p.classId==='bow'?new T.CylinderGeometry(.012,.012,.55,5):new T.SphereGeometry(.09,8,6),new T.MeshBasicMaterial({color:p.classId==='bow'?0xb8a47d:0xff6a20}));m.position.copy(camera.position).addScaledVector(dir,.5);m.quaternion.setFromUnitVectors(new T.Vector3(0,1,0),dir);scene.add(m);m.visible=p.classId!=='bow';bullets.push({delay:p.classId==='bow'?.22:0,m,v:dir.multiplyScalar(p.classId==='bow'?ARROW_SPEED:19.8),age:0,damage:criticalDamage(weaponDamage()*magicBonus(),random(),critChance()),arrow:p.classId==='bow'});ctx.sfx?.(p.classId==='bow'?'bow':'fireball')}}
function meleeTarget(){const dir=new T.Vector3();camera.getWorldDirection(dir);return targets().filter(n=>n.hp>0&&n.g.visible).sort((a,b)=>camera.position.distanceToSquared(a.g.position)-camera.position.distanceToSquared(b.g.position)).find(n=>{const delta=n.g.position.clone().add(new T.Vector3(0,.7,0)).sub(camera.position);return delta.length()<2.6&&delta.normalize().dot(dir)>.65&&[.2,.4,.6,.8].every(t=>!ctx.blocked(camera.position.clone().lerp(n.g.position,t)))})}
